def transform_survey_763(records):
    """Transform survey records into a list of dictionaries."""
    result = []
    for record in records:
        if isinstance(record, dict):
            result.append({
                "slug": record.get("slug", ""),
                "n": record.get("n", 0),
                "total": record.get("total", 0)
            })
    return result

